INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Wins Town Women''s Probiotic Gummies (60 Gummies)', 'Viatu vya Probiotic za Wanawake Wins Town (Viatu 60)', 'Pastilles Probiotiques Féminines Wins Town (60 Pastilles)', 'supplements', 1590, 2500, '60 gummies', 'Viatu 60', '60 pastilles', 'assets/photoz/IMG-20260721-WA0149.jpg', 25, 4.7, 18, '["Popular"]', 'A chewable daily supplement formulated with 5 Billion CFUs of probiotics, prebiotics, D-mannose, and 100 mg of cranberry extract. Deliciously cranberry-flavored, these gummies support healthy vaginal pH, promote urinary tract function, and boost digestive immunity.', 'Nyongeza ya kila siku inayotafunwa, iliyotengenezwa na CFU Bilioni 5 za probiotics, prebiotics, D-mannose, na extracts za cranberry 100 mg. Viatu hivi vinavyojaa ladha ya cranberry vinaunga mkono pH ya afya ya vagina, kukuza utendaji wa njia ya mkojo, na kuongeza kinga ya mmeng''enyo.', 'Complément alimentaire quotidien mâchable formulé avec 5 milliards d''unités formant des colonies de probiotiques, prébiotiques, D-mannose et 100 mg d''extrait de canneberge. Délicieusement aromatisées à la canneberge, ces pastilles soutiennent un pH vaginal sain, favorisent la fonction urinaire et renforcent l''immunité digestive.', '["5 Billion CFU probiotics","Supports healthy vaginal pH","Promotes urinary tract function","Boosts digestive immunity"]', '["Probiotics za CFU Bilioni 5","Zinaunga mkono pH ya afya ya vagina","Kukuza utendaji wa njia ya mkojo","Kuongeza kinga ya mmeng''enyo"]', '["5 milliards de CFU probiotiques","Soutient un pH vaginal sain","Favorise la fonction urinaire","Renforce l''immunité digestive"]', 1);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Wins Town Collagen with Burn', 'Collagen ya Wins Town Pamoja na Burn', 'Collagène Wins Town avec Burn', 'supplements', 1250, 3200, 'Powder supplement', 'Nyongeza ya poda', 'Complément en poudre', 'assets/photoz/IMG-20260721-WA0159.jpg', 20, 4.6, 12, '[]', 'Dual-action wellness supplement powder combining multi-type collagen (Types I, II, III, V & X) with metabolism-boosting agents. Helps reduce visible cellulite, accelerate fat breakdown, and support skin elasticity, joint mobility, hair, and nails.', 'Poda ya afya yenye vitendo viwili inayochanganya collagen ya aina nyingi (Aina I, II, III, V na X) pamoja na viungo vinavyoongeza metabolismi. Inasaidia kupunguza seluliti inayoonekana, kuharakisha uvunjaji wa mafuta, na kuunga mkono unyevu wa ngozi, uhamaji wa viungo, nywele, na kucha.', 'Poudre de complément bien-être à double action combinant du collagène multi-types (Types I, II, III, V et X) avec des agents boosteurs de métabolisme. Aide à réduire la cellulite visible, accélérer la décomposition des graisses et soutenir l''élasticité de la peau, la mobilité articulaire, les cheveux et les ongles.', '["Multi-type collagen (I, II, III, V, X)","Reduces visible cellulite","Accelerates fat breakdown","Supports skin, joints, hair & nails"]', '["Collagen ya aina nyingi (I, II, III, V, X)","Inapunguza seluliti inayoonekana","Kuharakisha uvunjaji wa mafuta","Kusaidia ngozi, viungo, nywele na kucha"]', '["Collagène multi-types (I, II, III, V, X)","Réduit la cellulite visible","Accélère la décomposition des graisses","Soutient peau, articulations, cheveux & ongles"]', 2);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('5D Gluta Collagen Glowing Powder (1 kg)', '5D Gluta Collagen Glowing Powder (1 kg)', '5D Gluta Collagen Poudre Éclat (1 kg)', 'supplements', 3290, 4200, '1 kg powder', 'Poda 1 kg', '1 kg poudre', 'assets/photoz/IMG-20260721-WA0160.jpg', 15, 4.8, 14, '["Bestseller"]', 'High-potency dietary supplement delivering 20g of grass-fed bovine collagen peptides alongside glutathione, hyaluronic acid, and vitamin C. Designed to brighten complexions, improve skin firming, and support hair, nail, and joint health from within.', 'Nyongeza ya chakula yenye nguvu kubwa inayotoa collagen peptides 20g kutoka kwa ng''ombe waliolishwa kwa nyasi pamoja na glutathione, asidi ya hyaluronic, na vitamini C. Imetengenezwa kuboresha rangi ya ngozi, kuboresha uthabiti wa ngozi, na kuunga mkono afya ya nywele, kucha, na viungo.', 'Complément alimentaire haute puissance délivrant 20g de peptides de collagène bovin nourri à l''herbe aux côtés de glutathion, d''acide hyaluronique et de vitamine C. Conçu pour éclaircir les teintes, améliorer la fermeté de la peau et soutenir la santé des cheveux, ongles et articulations de l''intérieur.', '["20g grass-fed bovine collagen","Glutathione & hyaluronic acid","Brightens complexion","Supports hair, nail & joint health"]', '["Collagen peptides 20g za ng''ombe","Glutathione na asidi ya hyaluronic","Kuboresha rangi ya ngozi","Kusaidia afya ya nywele, kucha na viungo"]', '["20g collagène bovin nourri à l''herbe","Glutathion & acide hyaluronique","Éclaircit le teint","Soutient santé cheveux, ongles & articulations"]', 3);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Duozi Marine Collagen+ 5-in-1', 'Duozi Marine Collagen+ 5-in-1', 'Duozi Marine Collagen+ 5-en-1', 'supplements', 2099, 3200, 'Powder supplement', 'Nyongeza ya poda', 'Complément en poudre', 'assets/photoz/IMG-20260721-WA0179.jpg', 18, 4.7, 10, '["New"]', 'A powdered dietary supplement containing marine collagen, biotin, vitamin C, melatonin, and hyaluronic acid for skin elasticity, hair/nail support, and anti-aging.', 'Nyongeza ya chakula ya poda inayokuwa na collagen ya baharini, biotin, vitamini C, melatonin, na asidi ya hyaluronic kwa unyevu wa ngozi, msaada wa nywele/kucha, na kupunguza ukale.', 'Complément alimentaire en poudre contenant du collagène marin, de la biotine, de la vitamine C, de la mélatonine et de l''acide hyaluronique pour l''élasticité de la peau, le soutien cheveux/ongles et l''anti-âge.', '["Marine collagen source","Contains biotin & vitamin C","Supports skin elasticity","Anti-aging formula"]', '["Chanzo cha collagen ya baharini","Ina biotin na vitamini C","Kusaidia unyevu wa ngozi","Fomula ya kupunguza ukale"]', '["Source de collagène marin","Contient biotine & vitamine C","Soutient l''élasticité cutanée","Formule anti-âge"]', 4);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Multi Collagen Peptides Powder (1 lb / 454g)', 'Multi Collagen Peptides Powder (1 lb / 454g)', 'Poudre Multi Collagène Peptides (1 lb / 454g)', 'supplements', 2499, 3500, '454g powder', 'Poda 454g', '454g poudre', 'assets/photoz/IMG-20260721-WA0180.jpg', 20, 4.7, 15, '[]', 'Hydrolyzed multi-collagen types I, II, III, V, & X infused with biotin, vitamin C, and hyaluronic acid to promote joint, skin, hair, and nail health.', 'Collagen ya aina nyingi iliyeyeyushwa I, II, III, V, na X iliyojumuishwa na biotin, vitamini C, na asidi ya hyaluronic ili kukuza afya ya viungo, ngozi, nywele, na kucha.', 'Multi-collagène hydrolysé types I, II, III, V et X enrichi en biotine, vitamine C et acide hyaluronique pour promouvoir la santé des articulations, de la peau, des cheveux et des ongles.', '["Hydrolyzed multi-type collagen","Infused with biotin & vitamin C","Promotes joint & skin health","Supports hair & nail growth"]', '["Collagen ya aina nyingi iliyeyeyushwa","Iliyojumuishwa na biotin na vitamini C","Kukuza afya ya viungo na ngozi","Kusaidia ukuaji wa nywele na kucha"]', '["Collagène multi-types hydrolysé","Enrichi en biotine & vitamine C","Promeut la santé articulaire & cutanée","Soutient la croissance cheveux & ongles"]', 5);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Gluta Master Collagen Glowing Powder - Vanilla (1 kg)', 'Gluta Master Collagen Glowing Powder - Vanilla (1 kg)', 'Gluta Master Collagène Poudre Éclat - Vanille (1 kg)', 'supplements', 2899, 5800, '1 kg powder', 'Poda 1 kg', '1 kg poudre', 'assets/photoz/IMG-20260721-WA0183.jpg', 12, 4.8, 11, '["Premium"]', 'Vanilla-flavored collagen supplement powder containing bovine collagen peptides, glutathione, and vitamin C. Works from the inside out to brighten skin tone, fade fine lines, rebuild skin firmness, and strengthen hair and nails.', 'Poda ya nyongeza ya collagen yenye ladha ya vanilla inayokuwa na collagen peptides za ng''ombe, glutathione, na vitamini C. Inafanya kazi kutoka ndani nje kuboresha rangi ya ngozi, kupunguza mistari miembamba, kujenga uthabiti wa ngozi, na kuimarisha nywele na kucha.', 'Poudre de complément au collagène saveur vanille contenant des peptides de collagène bovin, du glutathion et de la vitamine C. Agit de l''intérieur pour éclaircir le teint, atténuer les rides fines, restaurer la fermeté cutanée et renforcer cheveux et ongles.', '["Vanilla-flavored collagen powder","Bovine collagen peptides & glutathione","Brightens skin tone","Strengthens hair & nails"]', '["Poda ya collagen yenye ladha ya vanilla","Collagen peptides za ng''ombe na glutathione","Kuboresha rangi ya ngozi","Kuimarisha nywele na kucha"]', '["Poudre de collagène saveur vanille","Peptides de collagène bovin & glutathion","Éclaircit le teint","Renforce cheveux & ongles"]', 6);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('5D Gluta Plant-Based Protein 100% Whey (1 kg)', '5D Gluta Plant-Based Protein 100% Whey (1 kg)', '5D Gluta Protéine Végétale 100% Whey (1 kg)', 'supplements', 1999, NULL, '1 kg powder', 'Poda 1 kg', '1 kg poudre', 'assets/photoz/IMG-20260721-WA0184.jpg', 22, 4.5, 8, '[]', 'A 1kg dietary protein drink mix formula designed for daily nutrition, muscle recovery, and overall skin support.', 'Fomula ya protini ya kunywa 1 kg iliyotengenezwa kwa lishe ya kila siku, urejeshaji wa misa, na msaada wa jumla wa ngozi.', 'Formule de boisson protéinée diététique de 1 kg conçue pour la nutrition quotidienne, la récupération musculaire et le soutien cutané global.', '["100% whey protein","Supports muscle recovery","Daily nutrition formula","Skin support benefits"]', '["Protini ya whey 100%","Kusaidia urejeshaji wa misa","Fomula ya lishe ya kila siku","Manufaa ya msaada wa ngozi"]', '["100% protéine whey","Soutient la récupération musculaire","Formule nutrition quotidienne","Bienfaits de soutien cutané"]', 7);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Daynee Evening Primrose Oil Gummies (60s)', 'Daynee Evening Primrose Oil Gummies (Viatu 60)', 'Daynee Pastilles Huile d''Oe-nothère (60)', 'supplements', 1050, 2280, '60 gummies', 'Viatu 60', '60 pastilles', 'assets/photoz/IMG-20260721-WA0187.jpg', 20, 4.6, 9, '[]', 'Gummy supplements containing evening primrose oil to support hormonal balance, PMS relief, and healthy skin.', 'Viatu vya nyongeza vinavyokuwa na mafuta ya evening primrose ili kusaidia usawa wa homoni, kupunguza PMS, na ngozi yenye afya.', 'Pastilles complémentaires contenant de l''huile d''oe-nothère pour soutenir l''équilibre hormonal, le soulagement du syndrome prémenstruel et une peau saine.', '["Supports hormonal balance","PMS relief","Promotes healthy skin","Evening primrose oil enriched"]', '["Kusaidia usawa wa homoni","Kupunguza PMS","Kukuza ngozi yenye afya","Iliyojumuishwa na mafuta ya evening primrose"]', '["Soutient l''équilibre hormonal","Soulage le SPMS","Favorise une peau saine","Enrichie en huile d''oe-nothère"]', 8);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Daynee Calcium + D3 Gummies', 'Daynee Calcium + D3 Gummies', 'Daynee Pastilles Calcium + D3', 'supplements', 1350, 2500, '60 gummies', 'Viatu 60', '60 pastilles', 'assets/photoz/IMG-20260721-WA0188.jpg', 22, 4.7, 12, '[]', 'Dietary gummy supplements packed with calcium and vitamin D3 to promote strong bones, teeth, and immune function.', 'Viatu vya nyongeza ya chakula vilivyojaa calcium na vitamini D3 ili kukuza mifupa imara, meno, na utendaji wa kinga.', 'Pastilles complémentaires alimentaires riches en calcium et en vitamine D3 pour promouvoir des os, des dents et une fonction immunitaire solides.', '["Calcium & vitamin D3","Promotes strong bones & teeth","Supports immune function","Delicious gummy form"]', '["Calcium na vitamini D3","Kukuza mifupa imara na meno","Kusaidia utendaji wa kinga","Fomula ya viatu ladha"]', '["Calcium & vitamine D3","Favorise os & dents solides","Soutient la fonction immunitaire","Forme de pastille délicieuse"]', 9);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Daynee Magnesium Glycinate Gummies (60s, 600mg)', 'Daynee Magnesium Glycinate Gummies (Viatu 60, 600mg)', 'Daynee Pastilles Magnésium Glycinate (60, 600mg)', 'supplements', 1099, 2200, '60 gummies, 600mg', 'Viatu 60, 600mg', '60 pastilles, 600mg', 'assets/photoz/IMG-20260721-WA0189.jpg', 20, 4.8, 14, '["Popular"]', 'High-absorption magnesium complex gummies formulated to promote calm and relaxation, improve sleep, and support muscle, joint, and bone health.', 'Viatu vya magnesium complex vinavyokunywa vizuri vilivyotengenezwa kukuza upole na upumziko, kuboresha usingizi, na kuunga mkono afya ya misa, viungo, na mifupa.', 'Pastilles de complexe magnésium à haute absorption formulées pour promouvoir le calme et la relaxation, améliorer le sommeil et soutenir la santé musculaire, articulaire et osseuse.', '["High-absorption magnesium glycinate","Promotes calm & relaxation","Improves sleep quality","Supports muscle & bone health"]', '["Magnesium glycinate inayokunywa vizuri","Kukuza upole na upumziko","Kuboresha ubora wa usingizi","Kusaidia afya ya misa na mifupa"]', '["Magnésium glycinate à haute absorption","Favorise calme & relaxation","Améliore la qualité du sommeil","Soutient santé musculaire & osseuse"]', 10);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Daynee Vitamin C Gummies (60s, 250mg)', 'Daynee Vitamin C Gummies (Viatu 60, 250mg)', 'Daynee Pastilles Vitamine C (60, 250mg)', 'supplements', 1450, 2200, '60 gummies, 250mg', 'Viatu 60, 250mg', '60 pastilles, 250mg', 'assets/photoz/IMG-20260721-WA0192.jpg', 25, 4.7, 16, '[]', 'Vegan gummy supplements high in Vitamin C to support immune system health, provide antioxidant protection, and boost iron absorption.', 'Viatu vya mboga vinavyokuwa na Vitamini C nyingi ili kusaidia afya ya mfumo wa kinga, kutoa ulinzi wa antioxidants, na kuongeza uchukuaji wa chuma.', 'Pastilles véganes riches en vitamine C pour soutenir la santé immunitaire, fournir une protection antioxydante et améliorer l''absorption du fer.', '["High vitamin C content","Vegan-friendly formula","Immune system support","Boosts iron absorption"]', '["Maudhui ya vitamini C ya juu","Fomula rafiki kwa mboga","Msaada wa mfumo wa kinga","Kuongeza uchukuaji wa chuma"]', '["Riche en vitamine C","Formule végane","Soutien du système immunitaire","Améliore l''absorption du fer"]', 11);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Jiake Ultimate Maca Protein Powder (300g)', 'Jiake Ultimate Maca Protein Powder (300g)', 'Jiake Poudre Protéinée Maca Ultime (300g)', 'supplements', 4275, NULL, '300g powder', 'Poda 300g', '300g poudre', 'assets/photoz/IMG-20260721-WA0195.jpg', 10, 4.5, 6, '[]', 'High-potency 15:1 concentrate formula blending maca root, aguaje, fenugreek, tribulus, and dong quai designed to promote hip and curve enhancement.', 'Fomula ya mkusanyiko 15:1 yenye nguvu kubwa inayochanganya mizizi ya maca, aguaje, alfalfa, tribulus, na dong quai iliyotengenezwa kukuza urekebishaji wa viuno na mikunjo.', 'Formule concentrée 15:1 haute puissance mélangeant racine de maca, aguaje, fenugrec, tribulus et dong quai conçue pour favoriser l''amélioration des hanches et des courbes.', '["15:1 concentrate formula","Maca root blend","Promotes body contouring","Natural herbal ingredients"]', '["Fomula ya mkusanyiko 15:1","Mchanganyiko wa mizizi ya maca","Kukuza urekebishaji wa mwili","Viungo vya mimea asili"]', '["Formule concentrée 15:1","Mélange racine de maca","Favorise la silhouette","Ingrédients à base de plantes"]', 12);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('WinsTown / Daynee Assorted Health Gummies (Display Set)', 'WinsTown / Daynee Assorted Health Gummies (Set ya Kuonyesha)', 'WinsTown / Daynee Pastilles Santé Assorties (Ensemble)', 'supplements', 1550, 2200, 'Per bottle', 'Kwa chupa', 'Par bouteille', 'assets/photoz/IMG-20260721-WA0197.jpg', 30, 4.6, 8, '["New"]', 'A wide variety display of specialized 60-gummy dietary supplements including Sea Moss, Keto+ACV, Probiotics, BBL Gummies, and Glutathione Whitening.', 'Onyesho la aina mbalimbali za viatu vya nyongeza ya chakula vya vidonge 60 ikiwa ni pamoja na Sea Moss, Keto+ACV, Probiotics, BBL Gummies, na Glutathione Whitening.', 'Large variété de compléments alimentaires en pastilles spécialisées de 60 incluant Sea Moss, Keto+ACV, Probiotiques, BBL Pastilles et Glutathion Éclaircissant.', '["Multiple supplement varieties","Sea Moss, Keto+ACV, Probiotics","BBL & Glutathione options","60 gummies per bottle"]', '["Aina nyingi za nyongeza","Sea Moss, Keto+ACV, Probiotics","Chaguzi za BBL na Glutathione","Viatu 60 kwa chupa"]', '["Variétés de compléments multiples","Sea Moss, Keto+ACV, Probiotiques","Options BBL & Glutathion","60 pastilles par bouteille"]', 13);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('MTM-100 Sildenafil Citrate Tablets (100mg, 4s)', 'MTM-100 Sildenafil Citrate Tablets (100mg, Vidonge 4)', 'MTM-100 Comprimés Citrate de Sildénafil (100mg, 4)', 'supplements', 500, NULL, '4 tablets', 'Vidonge 4', '4 comprimés', 'assets/photoz/IMG-20260721-WA0198.jpg', 40, 4.4, 20, '[]', 'Oral prescription tablet blister pack (4s) indicated for the treatment and management of erectile dysfunction.', 'Vidonge vya dawa ya mdomo (vidonge 4) vinavyotumika kutibu na kusimamia matatizo ya upenyezaji.', 'Plaquette de comprimés oraux sur ordonnance (4s) indiqués pour le traitement et la gestion de la dysfonction érectile.', '["100mg sildenafil citrate","Treatment for erectile dysfunction","4-tablet blister pack","Prescription medication"]', '["Sildenafil citrate 100mg","Dawa ya kutibu matatizo ya upenyezaji","Kifurushi cha vidonge 4","Dawa ya daktari"]', '["Citrate de sildénafil 100mg","Traitement de la dysfonction érectile","Plaquette de 4 comprimés","Médicament sur ordonnance"]', 14);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('CeraVe Moisturising Cream (16 oz / 454 g)', 'CeraVe Cream ya Kupaka (16 oz / 454 g)', 'Crème Hydratante CeraVe (16 oz / 454 g)', 'skincare', 2099, 3650, '454g tub', 'Chupa 454g', 'Pot 454g', 'assets/photoz/IMG-20260721-WA0155.jpg', 15, 4.9, 25, '["Bestseller"]', 'Dermatologist-developed moisturizing cream for dry to very dry skin. Powered by 3 essential ceramides, hyaluronic acid, and MVE continuous-release technology, it restores the skin''s natural barrier and provides 24-hour hydration for face and body.', 'Cream ya kuporesha iliyotengenezwa na daktari wa ngozi kwa ngozi kavu hadi kavu sana. Inaendeshwa na ceramide 3 muhimu, asidi ya hyaluronic, na teknolojia ya MVE ya kuachilia endelevu, inarejesha kikomo cha asili cha ngozi na inatoa unyevu wa masaa 24 kwa uso na mwili.', 'Crème hydratante développée par des dermatologues pour les peaux sèches à très sèches. Alimentée par 3 céramides essentiels, l''acide hyaluronique et la technologie à libération continue MVE, elle restaure la barrière naturelle de la peau et offre une hydratation de 24 heures pour le visage et le corps.', '["3 essential ceramides","Hyaluronic acid & MVE technology","24-hour hydration","For face & body"]', '["Ceramide 3 muhimu","Asidi ya hyaluronic na teknolojia ya MVE","Unyevu wa masaa 24","Kwa uso na mwili"]', '["3 céramides essentiels","Acide hyaluronique & technologie MVE","Hydratation 24 heures","Pour le visage & le corps"]', 15);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Osckal Alpha Arbutin 3 Plus Whitening Body Soap', 'Osckal Alpha Arbutin 3 Plus Whitening Body Soap', 'Savon Corporel Osckal Alpha Arbutin 3 Plus Éclaircissant', 'skincare', 1350, 1500, 'Body soap', 'Sabuni ya mwili', 'Savon corporel', 'assets/photoz/IMG-20260721-WA0178.jpg', 25, 4.5, 10, '[]', 'A body soap formulated with alpha arbutin to target dark spots, hyperpigmentation, and uneven skin tone while providing hydration and anti-aging benefits.', 'Sabuni ya mwili iliyotengenezwa na alpha arbutin kulenga mafundo meusi, hyperpigmentation, na rangi isiyofautika ya ngozi huku ikitoa unyevu na manufaa ya kupunguza ukale.', 'Savon corporel formulé avec l''alpha arbutin pour cerner les taches sombres, l''hyperpigmentation et le teint inégal tout en offrant hydratation et bienfaits anti-âge.', '["Alpha arbutin formula","Targets dark spots","Anti-aging benefits","Hydrating body soap"]', '["Fomula ya alpha arbutin","Inalenga mafundo meusi","Manufaa ya kupunguza ukale","Sabuni ya mwili yenye unyevu"]', '["Formule alpha arbutin","Cible les taches sombres","Bienfaits anti-âge","Savon corporel hydratant"]', 16);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Sadoer Tea Tree Acnes Oil Control Face Cream', 'Sadoer Tea Tree Acnes Oil Control Face Cream', 'Crème Visage Sadoer Tea Tree Acnes Contrôle de Sébum', 'skincare', 489, NULL, 'Face cream', 'Cream ya uso', 'Crème pour le visage', 'assets/photoz/IMG-20260721-WA0185.jpg', 30, 4.4, 8, '[]', 'A gentle facial cream with tea tree extract designed to balance oil secretion, reduce acne marks, and lock in moisture.', 'Cream laini ya uso yenye extract ya tea tree iliyotengenezwa kusawazisha utengenezaji wa mafuta, kupunguza alama za chunusi, na kufunga unyevu.', 'Crème faciale douce avec extrait de tea tree conçue pour équilibrer la sécrétion de sébum, réduire les traces d''acné et fixer l''hydratation.', '["Tea tree extract","Controls oil secretion","Reduces acne marks","Locks in moisture"]', '["Extract ya tea tree","Kusawazisha utengenezaji wa mafuta","Kupunguza alama za chunusi","Kufunga unyevu"]', '["Extrait de tea tree","Équilibre la sécrétion de sébum","Réduit les traces d''acné","Fixe l''hydratation"]', 17);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Dr. Meinaier Vitamin C & Pure Collagen Sugar Scrub (650g)', 'Dr. Meinaier Vitamin C & Pure Collagen Sugar Scrub (650g)', 'Gommage Sucre Dr. Meinaier Vitamine C & Collagène Pur (650g)', 'skincare', 499, 1200, '650g scrub', 'Scrub 650g', '650g gommage', 'assets/photoz/IMG-20260721-WA0191.jpg', 18, 4.6, 11, '[]', 'An exfoliating body sugar scrub containing Vitamin C and Collagen designed to brighten skin tone, fade dark spots, and deeply hydrate.', 'Scrub ya sukari ya mwili inayosafisha ikijumuisha Vitamini C na Collagen iliyotengenezwa kuboresha rangi ya ngozi, kupunguza mafundo meusi, na kuweka unyevu wa kina.', 'Gommage corporel au sucre contenant de la vitamine C et du collagène conçu pour éclaircir le teint, atténuer les taches sombres et hydrater en profondeur.', '["Vitamin C & collagen enriched","Exfoliating sugar scrub","Brightens skin tone","Deep hydration"]', '["Iliyojumuishwa na Vitamini C na Collagen","Scrub ya sukari inayosafisha","Kuboresha rangi ya ngozi","Unyevu wa kina"]', '["Enrichie vitamine C & collagène","Gommage sucré exfoliant","Éclaircit le teint","Hydratation profonde"]', 18);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Dove Exfoliating Body Polish / Body Scrub', 'Dove Exfoliating Body Polish / Body Scrub', 'Dove Polish Corporel Exfoliant / Gommage Corporel', 'bodycare', 1049, 1850, 'Body scrub', 'Scrub ya mwili', 'Gommage corporel', 'assets/photoz/IMG-20260721-WA0156.jpg', 20, 4.7, 14, '["Popular"]', 'Gentle exfoliating scrub featuring Dove''s signature ¼ moisturizing cream formula. Formulated with botanical extracts like Himalayan Salt & Rose Oil or Pomegranate Seeds & Shea Butter to buff away dead skin cells and reveal smooth, radiant skin.', 'Scrub laini inayo safisha ikijumuisha fomula ya Dove ya ¼ ya cream ya kuporesha. Imetengenezwa na extract za mimea kama vile Chumvi ya Himalayan na Mafuta ya Waridi au Mbegu za Pomegranate na Shea Butter kuondoa seli zilizokufa na kuonyesha ngozi laini, inayong''aa.', 'Gommage exfoliant doux avec la formule signature ¼ crème hydratante de Dove. Formulé avec des extraits botaniques comme le sel himalayen et l''huile de rose ou les graines de grenade et le beurre de karité pour éliminer les cellules mortes et révéler une peau lisse et éclatante.', '["¼ moisturizing cream formula","Botanical extracts","Buff away dead skin cells","Smooth, radiant skin"]', '["Fomula ya ¼ cream ya kuporesha","Extract za mimea","Kuondoa seli zilizokufa","Ngozi laini, inayong''aa"]', '["Formule ¼ crème hydratante","Extraits botaniques","Élimine les cellules mortes","Peau lisse et éclatante"]', 19);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Kormesic 100% Raw Batana Oil', 'Kormesic 100% Raw Batana Oil', 'Kormesic Huile de Batana brute 100%', 'bodycare', 350, NULL, 'Hair oil', 'Mafuta ya nywele', 'Huile pour cheveux', 'assets/photoz/IMG-20260721-WA0181.jpg', 35, 4.5, 7, '[]', 'Raw, unrefined batana oil focused on stimulating hair growth, strengthening strands, activating hair follicles, and repairing damage.', 'Mafuta ya batana ghafi, isiyosindikwa, iliyolengwa kuchochea ukuaji wa nywele, kuimarisha nyuzi, kuwasha follicles za nywele, na kurekebisha uharibifu.', 'Huile de batana brute, non raffinée, conçue pour stimuler la pousse des cheveux, renforcer les mèches, activer les follicules pileux et réparer les dommages.', '["100% raw & unrefined","Stimulates hair growth","Strengthens hair strands","Repairs hair damage"]', '["100% ghafi na isiyosindikwa","Kuchochea ukuaji wa nywele","Kuimarisha nyuzi za nywele","Kurekebisha uharibifu wa nywele"]', '["100% brute & non raffinée","Stimule la pousse des cheveux","Renforce les mèches","Répare les dommages capillaires"]', 20);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Best Collagen Serum Body Oil (Yellow)', 'Best Collagen Serum Body Oil (Njano)', 'Huile Corporelle Sérum Collagène Best (Jaune)', 'bodycare', 1250, 1800, 'Body oil serum', 'Sérum ya mafuta ya mwili', 'Sérum huile corporelle', 'assets/photoz/IMG-20260721-WA0193.jpg', 18, 4.6, 9, '[]', 'A collagen-enriched body serum formulated with Vitamin D to deeply hydrate, repair sun damage, reduce fine lines, and improve skin barrier elasticity.', 'Sérum ya mwili iliyojumuishwa na collagen iliyotengenezwa na Vitamini D kuweka unyevu wa kina, kurekebisha uharibifu wa jua, kupunguza mistari miembamba, na kuboresha unyevu wa kikomo cha ngozi.', 'Sérum corporel enrichi au collagène formulé avec la vitamine D pour hydrater en profondeur, réparer les dommages solaires, réduire les rides fines et améliorer l''élasticité de la barrière cutanée.', '["Collagen-enriched serum","Vitamin D formula","Deep hydration & repair","Reduces fine lines"]', '["Sérum iliyojumuishwa na collagen","Fomula ya Vitamini D","Unyevu wa kina na ukarabati","Kupunguza mistari miembamba"]', '["Sérum enrichi au collagène","Formule Vitamine D","Hydratation & réparation profondes","Réduit les rides fines"]', 21);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Best Collagen White Body Oil Extra Whitening (Pink, 500ml)', 'Best Collagen White Body Oil Extra Whitening (Waridi, 500ml)', 'Huile Corporelle Blanche Collagène Best Extra Éclaircissante (Rose, 500ml)', 'bodycare', 1250, 1800, '500ml body oil', 'Mafuta ya mwili 500ml', '500ml huile corporelle', 'assets/photoz/IMG-20260721-WA0194.jpg', 18, 4.5, 7, '[]', 'An extra-strong body oil serum infused with Vitamin D designed to target dark spots, brighten the complexion, and tone skin texture.', 'Sérum ya mafuta ya mwili iliyoimarishwa iliyojumuishwa na Vitamini D iliyotengenezwa kulenga mafundo meusi, kuboresha rangi ya ngozi, na kusawazisha muundo wa ngozi.', 'Sérum huile corporelle extra-fort enrichi en vitamine D conçu pour cerner les taches sombres, éclaircir le teint et tonifier la texture de la peau.', '["Extra-strength formula","Vitamin D infused","Targets dark spots","Tones skin texture"]', '["Fomula iliyoimarishwa","Iliyojumuishwa na Vitamini D","Inalenga mafundo meusi","Kusawazisha muundo wa ngozi"]', '["Formule extra-forte","Enrichie vitamine D","Cible les taches sombres","Tonifie la texture cutanée"]', 22);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Sajed Mamool Incense (100 g)', 'Sajed Mamool Incense (100 g)', 'Encens Sajed Mamool (100 g)', 'wellness', 850, 1200, '100g incense', 'Ungo 100g', '100g encens', 'assets/photoz/IMG-20260721-WA0172.jpg', 20, 4.6, 8, '[]', 'Traditional Middle Eastern bakhoor incense tablets crafted with floral and woody aromatic notes. Designed for charcoal or electric burners to disperse long-lasting, rich scents through living spaces, prayer areas, and garments.', 'Vidonge vya ungo wa bakhoor wa jadi wa Mashariki ya Kati vilivyotengenezwa kwa alama za harufu za ua na mbao. Vilivyoundwa kwa mashabaha ya makaa au umeme kusambaza harufu ndefu, tajiri katika nafasi zaishi, maeneo ya kuombea, na nguo.', 'Tablettes d''encens bakhoor traditionnel du Moyen-Orient élaborées avec des notes aromatiques florales et boisées. Conçues pour les brûleurs à charbon ou électriques pour diffuser des parfums riches et durables dans les espaces de vie, les zones de prière et les vêtements.', '["Traditional Middle Eastern bakhoor","Floral & woody notes","Long-lasting fragrance","For living spaces & garments"]', '["Bakhoor ya jadi ya Mashariki ya Kati","Alama za ua na mbao","Harufu ndefu","Kwa nafasi zaishi na nguo"]', '["Bakhoor traditionnel moyen-oriental","Notes florales & boisées","Parfum durable","Pour espaces & vêtements"]', 23);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('WinsTown Slim Plus Fat Burner (60 Capsules)', 'WinsTown Slim Plus Fat Burner (Vidonge 60)', 'WinsTown Slim Plus Brûleur de Graisse (60 Gélules)', 'wellness', 1550, 1800, '60 capsules', 'Vidonge 60', '60 gélules', 'assets/photoz/IMG-20260721-WA0182.jpg', 22, 4.5, 10, '[]', 'A 60-capsule healthy detox dietary supplement designed to boost metabolism, aid in fat breakdown, and suppress appetite.', 'Nyongeza ya chakula ya afya ya vidonge 60 iliyotengenezwa kuongeza metabolismi, kusaidia uvunjaji wa mafuta, na kuzuia hamu ya kula.', 'Complément alimentaire détox sain en 60 gélules conçu pour booster le métabolisme, aider à la décomposition des graisses et supprimer l''appétit.', '["60-capsule detox formula","Boosts metabolism","Aids fat breakdown","Suppresses appetite"]', '["Fomula ya detox ya vidonge 60","Kuongeza metabolismi","Kusaidia uvunjaji wa mafuta","Kuzuia hamu ya kula"]', '["Formule détox 60 gélules","Booster le métabolisme","Aide à la décomposition des graisses","Supprime l''appétit"]', 24);
